28: const buildRedirectToBasePath = (basePath: string): RoutesObject => ({
29:   SUBPATH_DEFAULT: {
30:     path: `${basePath}/*`,
31:     component: (): React.FunctionComponentElement<any> => {
32:       // eslint-disable-next-line react-hooks/rules-of-hooks
33:       const pathVariables: { [key: string]: string } = useParams();
34:       const effectiveBasePath = resolvePathVariables(basePath, pathVariables);
35:       return <Redirect to={`${effectiveBasePath || basePath}`} />;
36:     },
37:   },
38: });
