1: import { appStateReducer } from '@pagopa/selfcare-common-frontend/lib/redux/slices/appStateSlice';
2: import { permissionsReducer } from '@pagopa/selfcare-common-frontend/lib/redux/slices/permissionsSlice';
3: import { userReducer } from '@pagopa/selfcare-common-frontend/lib/redux/slices/userSlice';
4: import { configureStore } from '@reduxjs/toolkit';
5: import logger from 'redux-logger';
6: import { LOG_REDUX_ACTIONS } from '../utils/constants';
7: 
8: const additionalMiddlewares = [LOG_REDUX_ACTIONS ? logger : undefined];
9: 
10: export const createStore = () =>
11:   configureStore({
12:     reducer: {
13:       user: userReducer,
14:       permissions: permissionsReducer,
15:       appState: appStateReducer,
16:     },
17:     middleware: (getDefaultMiddleware: any) =>
18:       additionalMiddlewares.reduce(
19:         (array, middleware) => (middleware ? array.concat(middleware) : array),
20:         getDefaultMiddleware({ serializableCheck: false })
21:       ),
22:   });
23: 
24: export const store = createStore();
25: 
26: // Infer the `RootState` and `AppDispatch` types from the store itself
27: export type RootState = ReturnType<typeof store.getState>;
28: // Inferred type: {posts: PostsState, comments: CommentsState, users: UsersState}
29: export type AppDispatch = typeof store.dispatch;

