1: import { Router } from 'react-router-dom';
2: import { Provider } from 'react-redux';
3: import { ThemeProvider } from '@mui/material';
4: import { I18nextProvider } from 'react-i18next';
5: import { ReactNode, useEffect, useState } from 'react';
6: import { CONFIG as LOCAL_CONFIG } from '@pagopa/selfcare-common-frontend/lib/config/env';
7: import { ENV } from '../utils/env';
8: import { configureI18n } from '../locale/locale-utils';
9: import { DashboardMicrocomponentsProps } from '../microcomponents/dashboard-routes-utils';
10: 
11: type Props = DashboardMicrocomponentsProps & {
12:   children: ReactNode;
13: };
14: 
15: const RemotePage = ({ history, store, i18n, theme, children, CONFIG }: Props) => {
16:   const [loaded, setLoaded] = useState(false);
17: 
18:   useEffect(() => {
19:     if (!loaded) {
20:       configureI18n(i18n);
21: 
22:       // eslint-disable-next-line functional/immutable-data
23:       ENV.STORE = store;
24:       // eslint-disable-next-line functional/immutable-data
25:       ENV.i18n = i18n;
26:       // eslint-disable-next-line functional/immutable-data
27:       Object.assign(LOCAL_CONFIG, CONFIG);
28: 
29:       setLoaded(true);
30:     }
31:   }, []);
32: 
33:   return (
34:     <Provider store={store}>
35:       <Router history={history}>
36:         <I18nextProvider i18n={i18n}>
37:           <ThemeProvider theme={theme}>{children}</ThemeProvider>
38:         </I18nextProvider>
39:       </Router>
40:     </Provider>
41:   );
42: };
43: 
44: export default RemotePage;

